using EEMS.Modules.Results.Domain;namespace EEMS.UnitTests.Results;public sealed class ResultTests{[Fact]public void VotesCannotBeNegative()=>Assert.Throws<ArgumentOutOfRangeException>(()=>ResultDetail.Create(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),-1));[Fact]public void SubmitterCannotVerify(){var u=Guid.NewGuid();Assert.Throws<InvalidOperationException>(()=>ResultVerification.Record(Guid.NewGuid(),Guid.NewGuid(),u,u,2,"ok"));}[Fact]public void SubmissionTransitionIncrementsVersion(){var s=ResultSubmission.Create(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),1,Guid.NewGuid(),1,"key",10);s.MoveTo(2);Assert.Equal(2,s.Version);}}
